///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.hideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "CO_SUM_CNT", "Show", false);
        if (scwin.gBondYn === 'Y') {
            $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", true);
        } else {
            if (scwin.gLdMktTp === '1') {
                $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", true);
            } else if (scwin.gLdMktTp === '2') {
                $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", true);
            } else if (scwin.gLdMktTp === '9') {
                $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", true);
                $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", true);
                $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", true);
                $c.cm.setColumnProp(grd_Grid, "CO_SUM_CNT", "Show", true);
                $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Name", '유가;상장회사수');
                $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Name", '코스닥;상장회사수');
            }
        }
        const gYYYY = $c.ut.cGetToday("yyyymmdd").substring(0, 4);
        let gMemo = '※ 상장회사수는 주권에 한하며, ' + gYYYY + '년도 기준 데이터 입니다.';
        if (scwin.gBondYn === 'Y') {
            $c.cm.setColumnProp(grd_Grid, "CO_COUNT", "Name", '채권공시;법인수');
            gMemo = '※ 채권공시법인 회사수는  ' + gYYYY + '년도 기준 데이터 입니다.(채권의 경우 결산월이 여러개인 경우 결산월마다 count 됩니다.)';
        }
        txb_memo.setValue(gMemo);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26602.onpageload" });
    }
};

