/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26602.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "제출기한관리목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26602.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (js_svrGubun !== 'dr') {
            await scwin.read(grd_Grid, row, colid);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26602.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26602.dts_Grid_OnLoadError" });
    }
};

