///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10) + 2;
    let str = "";
    for (let i = yyyy; i >= 1980; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;
    cmb_YYYY.setValue(ToDay.getYear());
};

/**
