/**
 * @method
 * @name readForView
 * @description 수정팝업
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} gubun gubun
 * @param {*} vBAS_YY vBAS_YY
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readForView = async function(GridID, row, gubun, vBAS_YY) {
    const CMD = "R";
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    const vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
    const vIGUBUN = gubun;
    if (await scwin.setParam(CMD, vBAS_YY, vIBAS_ACNTCLS_MM, vIGUBUN)) {
        // formal arguments
        const options = {
            id: "ULDSTF26604",
            title: "상세조회",
            type: "browserPopup",
            width: "480px",
            height: "190px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclsrch/ULDSTF26604.gfm", options);
    }
};

/**
 * @method
 * @name setParam
 * @description paramObj Update
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

